#include <bits/stdc++.h>using namespace std; int main() {    int T;    cin >> T;     while (T--) {        int n;        long long x;        cin >> n >> x;         if (n == 0) {            cout << 2 * x << endl;            continue;        }         vector<long long> a(n);        for (int i = 0; i < n; i++) {            cin >> a[i];        }         sort(a.begin(), a.end());         long long ans = a[0];   // gap from 0 to first station         for (int i = 1; i < n; i++) {            ans = max(ans, a[i] - a[i - 1]);        }         ans = max(ans, 2 * (x - a[n - 1]));         cout << ans << endl;    }    return 0;}